CREATE TABLE IF NOT EXISTS sr_user(id varchar(36) PRIMARY KEY,role varchar(10) NOT NULL,phone varchar(20) UNIQUE NOT NULL,email varchar(254) NOT NULL,name varchar(120) NOT NULL,password_hash varchar(100) NOT NULL,profile text NOT NULL,driver_code varchar(30) UNIQUE,created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sr_session(token_hash varchar(64) PRIMARY KEY,user_id varchar(36) REFERENCES sr_user(id),expires_at timestamp with time zone NOT NULL);
CREATE TABLE IF NOT EXISTS sr_link(id varchar(36) PRIMARY KEY,parent_id varchar(36) REFERENCES sr_user(id),driver_id varchar(36) REFERENCES sr_user(id),UNIQUE(parent_id,driver_id));
CREATE TABLE IF NOT EXISTS sr_child(id varchar(36) PRIMARY KEY,link_id varchar(36) REFERENCES sr_link(id),details text NOT NULL);
CREATE TABLE IF NOT EXISTS sr_schedule(child_id varchar(36) PRIMARY KEY REFERENCES sr_child(id),term_start date NOT NULL,term_end date NOT NULL,week text NOT NULL);
CREATE TABLE IF NOT EXISTS sr_override(child_id varchar(36) REFERENCES sr_child(id),journey_date date NOT NULL,absent boolean NOT NULL,legs text NOT NULL,PRIMARY KEY(child_id,journey_date));
CREATE TABLE IF NOT EXISTS sr_trip(id varchar(100) PRIMARY KEY,child_id varchar(36) REFERENCES sr_child(id),journey_date date NOT NULL,leg_index integer NOT NULL,state varchar(20) NOT NULL,details text NOT NULL,updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,UNIQUE(child_id,journey_date,leg_index));
CREATE TABLE IF NOT EXISTS sr_notification(id varchar(36) PRIMARY KEY,user_id varchar(36) REFERENCES sr_user(id),title varchar(120) NOT NULL,message varchar(1000) NOT NULL,child_id varchar(36),is_read boolean DEFAULT false,created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sr_position(driver_id varchar(36) PRIMARY KEY REFERENCES sr_user(id),latitude double precision NOT NULL,longitude double precision NOT NULL,captured_at timestamp with time zone NOT NULL);
CREATE TABLE IF NOT EXISTS sr_document(id varchar(36) PRIMARY KEY,user_id varchar(36) REFERENCES sr_user(id),mime varchar(30) NOT NULL,created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sr_payment(id varchar(36) PRIMARY KEY,driver_id varchar(36) REFERENCES sr_user(id),billing_month varchar(7) NOT NULL,amount decimal(12,2) NOT NULL,currency varchar(3) NOT NULL,selection text NOT NULL,state varchar(30) NOT NULL,poll_url text,browser_url text,idempotency_key varchar(100) NOT NULL,created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,UNIQUE(driver_id,idempotency_key));
CREATE TABLE IF NOT EXISTS sr_entitlement(link_id varchar(36) REFERENCES sr_link(id),billing_month varchar(7),payment_id varchar(36) REFERENCES sr_payment(id),PRIMARY KEY(link_id,billing_month));
CREATE TABLE IF NOT EXISTS sr_driver_listing(driver_id varchar(36) PRIMARY KEY REFERENCES sr_user(id), available boolean NOT NULL DEFAULT false, share_licence boolean NOT NULL DEFAULT false, route_details text NOT NULL);
CREATE TABLE IF NOT EXISTS sr_passenger_request(id varchar(36) PRIMARY KEY, parent_id varchar(36) REFERENCES sr_user(id), driver_id varchar(36) REFERENCES sr_user(id), details text NOT NULL, state varchar(20) NOT NULL, child_id varchar(36) REFERENCES sr_child(id), created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sr_terms_acceptance(user_id varchar(36) REFERENCES sr_user(id),version varchar(40),accepted_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,version));
CREATE TABLE IF NOT EXISTS sr_family_service(link_id varchar(36) PRIMARY KEY REFERENCES sr_link(id),enabled boolean NOT NULL,active_since date NOT NULL);
CREATE TABLE IF NOT EXISTS sr_child_billing_start(child_id varchar(36) PRIMARY KEY REFERENCES sr_child(id),starts date NOT NULL);
CREATE TABLE IF NOT EXISTS sr_child_charge(child_id varchar(36) REFERENCES sr_child(id),billing_month varchar(7),amount decimal(12,2) NOT NULL,paid boolean NOT NULL DEFAULT false,payment_id varchar(36) REFERENCES sr_payment(id),PRIMARY KEY(child_id,billing_month));
CREATE TABLE IF NOT EXISTS sr_rating_event(trip_id varchar(100) REFERENCES sr_trip(id),action varchar(10),parent_id varchar(36) REFERENCES sr_user(id),driver_id varchar(36) REFERENCES sr_user(id),child_name varchar(300),created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP,stars integer CHECK(stars BETWEEN 1 AND 5),rated_at timestamp with time zone,PRIMARY KEY(trip_id,action));
